-- Sync service landing copy with the six service cards while preserving media and portfolio relations.
update public.service_landings
set
  content_id = case slug
    when 'videotron-outdoor' then $$ {"eyebrow":"Solusi digital media","title":"Digital Media Solution","description":"Solusi layar LED indoor dan outdoor untuk menghadirkan visual yang jelas, konsisten, dan mudah diandalkan di berbagai ruang dan lokasi.","intro_eyebrow":"Dasar perencanaan","intro_title":"Media digital dirancang dari kebutuhan ruang dan audiens.","intro":"Digital media solution perlu disesuaikan dengan ukuran bidang, pixel pitch, brightness, jarak pandang, sumber konten, struktur, daya, dan akses perawatan agar hasil tampil optimal.","considerations_title":"Yang perlu dipastikan","considerations":["Ukuran bidang, pixel pitch, dan jarak pandang","Brightness sesuai kondisi indoor atau outdoor","Sumber konten, jalur listrik, dan sistem kontrol","Struktur pemasangan serta akses perawatan"],"process_eyebrow":"Alur kerja","process_title":"Tahapan dari kebutuhan hingga layar siap digunakan.","process":["Survei lokasi dan kebutuhan audiens","Menentukan spesifikasi layar dan konfigurasi","Menyiapkan struktur, daya, dan sistem kontrol","Pemasangan, pengujian visual, dan serah terima"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Bangun solusi media digital Anda.","cta_description":"Sampaikan lokasi, ukuran bidang, jarak pandang, dan kebutuhan konten agar konfigurasi LED dapat dirancang secara tepat.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
    when 'led-indoor' then $$ {"eyebrow":"Layanan media konvensional","title":"Conventional Media","description":"Media konvensional seperti billboard, lightbox, dan signage untuk menyampaikan pesan brand secara jelas di lokasi yang tepat.","intro_eyebrow":"Dasar perencanaan","intro_title":"Media fisik yang mengikuti lokasi dan arah pandang.","intro":"Conventional media perlu direncanakan dari lokasi, arah lalu lintas, ukuran bidang, material visual, struktur, pencahayaan, dan kebutuhan perawatan agar pesan mudah terlihat dan tahan digunakan.","considerations_title":"Yang perlu dipastikan","considerations":["Lokasi, arah pandang, dan profil audiens","Ukuran bidang serta rasio material visual","Struktur, material, dan ketahanan terhadap cuaca","Pencahayaan, daya, dan akses perawatan"],"process_eyebrow":"Alur kerja","process_title":"Tahapan membentuk media yang siap dipasang.","process":["Menganalisis lokasi dan peluang visibilitas","Menentukan format, ukuran, dan material","Menyiapkan desain, struktur, dan pencahayaan","Produksi, pemasangan, dan pemeriksaan akhir"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Rencanakan media konvensional Anda.","cta_description":"Kirimkan lokasi, ukuran bidang, dan tujuan komunikasi agar format billboard, lightbox, atau signage dapat ditentukan dengan tepat.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
    when 'rental-led' then $$ {"eyebrow":"Layanan architectural & media construction","title":"Architectural & Media Construction","description":"Solusi struktur sipil, interior, baja, facade, ballroom, dan media structure untuk membangun ruang serta media yang aman dan terintegrasi.","intro_eyebrow":"Dasar perencanaan","intro_title":"Konstruksi media yang menyatu dengan arsitektur.","intro":"Pekerjaan architectural and media construction perlu menyatukan fungsi ruang, struktur, beban, material, jalur instalasi, keselamatan, dan hasil akhir agar elemen media dapat terpasang dengan rapi dan aman.","considerations_title":"Yang perlu dipastikan","considerations":["Kondisi bangunan, dimensi, dan kebutuhan beban","Material facade, interior, baja, atau ballroom","Jalur listrik, kabel, akses kerja, dan keselamatan","Finishing, perawatan, serta integrasi dengan media"],"process_eyebrow":"Alur kerja","process_title":"Tahapan dari struktur hingga finishing.","process":["Meninjau gambar, lokasi, dan kebutuhan fungsi","Mengembangkan detail struktur dan material","Mengerjakan konstruksi, instalasi, dan koordinasi site","Pemeriksaan beban, finishing, dan serah terima"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Wujudkan ruang dan struktur media Anda.","cta_description":"Sampaikan gambar, kondisi lokasi, ukuran, dan kebutuhan media agar solusi konstruksi dapat dibahas bersama tim teknis.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
    when 'media-konvensional' then $$ {"eyebrow":"Layanan media placement & creative content","title":"Media Placement & Creative Content","description":"Strategi penempatan OOH dan DOOH yang dipadukan dengan konsep kreatif, produksi konten, dan campaign rollout untuk menjangkau audiens yang tepat.","intro_eyebrow":"Dasar perencanaan","intro_title":"Strategi media yang bertemu dengan ide kreatif.","intro":"Media placement and creative content perlu dimulai dari tujuan campaign, karakter audiens, lokasi, durasi, format media, pesan, dan kebutuhan produksi agar komunikasi brand terasa relevan.","considerations_title":"Yang perlu dipastikan","considerations":["Tujuan campaign dan profil audiens","Pilihan OOH, DOOH, lokasi, serta durasi tayang","Creative concept, format, dan kebutuhan produksi","Jadwal rollout, approval, dan pengukuran hasil"],"process_eyebrow":"Alur kerja","process_title":"Dari strategi hingga campaign berjalan.","process":["Memahami tujuan, audiens, dan media opportunity","Menyusun strategi placement dan creative concept","Memproduksi serta menyesuaikan aset konten","Menjalankan rollout dan mengevaluasi hasil"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Hubungkan placement dengan konten yang kuat.","cta_description":"Ceritakan tujuan campaign, audiens, lokasi, dan pesan utama agar strategi media serta konten kreatif dapat dirancang dalam satu alur.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
    when 'digital-signage' then $$ {"eyebrow":"Layanan audio visual","title":"Audio Visual","description":"Sistem audio visual terintegrasi untuk meeting room, ruang presentasi, venue, dan event dengan alur sinyal yang jelas dan mudah digunakan.","intro_eyebrow":"Dasar perencanaan","intro_title":"Sistem visual dan audio yang bekerja sebagai satu kesatuan.","intro":"Audio visual perlu disusun dari kebutuhan ruang, jumlah pengguna, akustik, display, audio, control system, signal flow, konektivitas, dan kebutuhan operasional harian.","considerations_title":"Yang perlu dipastikan","considerations":["Ukuran ruang, jumlah pengguna, dan akustik","Display, audio, microphone, dan control system","Signal flow, konektivitas, dan kompatibilitas perangkat","Kemudahan penggunaan, training, dan maintenance"],"process_eyebrow":"Alur kerja","process_title":"Tahapan membangun sistem yang mudah digunakan.","process":["Memahami fungsi ruang dan alur pengguna","Menentukan perangkat, signal flow, dan sistem kontrol","Melakukan instalasi, konfigurasi, dan integrasi","Testing, training, dan serah terima sistem"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Buat ruang Anda lebih terhubung.","cta_description":"Sampaikan jenis ruang, jumlah pengguna, perangkat yang tersedia, dan kebutuhan meeting atau event agar sistem audio visual dapat diintegrasikan secara tepat.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
    when 'event-production' then $$ {"eyebrow":"Layanan event production","title":"Event Production","description":"Dukungan produksi visual dan teknis untuk event, stage, conference, dan live experience dari setup hingga acara selesai.","intro_eyebrow":"Dasar perencanaan","intro_title":"Produksi yang mengikuti ritme acara.","intro":"Event production perlu menyatukan kebutuhan stage, screen, visual, signal, listrik, jadwal setup, rehearsal, rundown, dan technical operation agar acara berjalan lancar.","considerations_title":"Yang perlu dipastikan","considerations":["Format conference, stage, dan kebutuhan audiens","Screen, visual content, signal, audio, dan lighting","Jadwal setup, rehearsal, loading, dan safety","Pembagian peran serta dukungan technical operation"],"process_eyebrow":"Alur kerja","process_title":"Dari rundown hingga show day.","process":["Meninjau rundown, venue, dan kebutuhan teknis","Menyusun stage, screen, signal, dan production plan","Setup perangkat, routing signal, dan rehearsal","Technical operation saat live event dan breakdown"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Siapkan event dengan tim yang terkoordinasi.","cta_description":"Kirimkan rundown, venue, jadwal, dan kebutuhan visual agar dukungan produksi dapat disusun secara aman dan terukur.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"} $$::jsonb
  end,
  content_en = case slug
    when 'videotron-outdoor' then $$ {"eyebrow":"Digital media solution","title":"Digital Media Solution","description":"Indoor and outdoor LED display solutions that deliver clear, consistent, and dependable visuals across different spaces and locations.","intro_eyebrow":"Planning basis","intro_title":"Digital media shaped by the space and audience.","intro":"A digital media solution should account for display size, pixel pitch, brightness, viewing distance, content sources, structure, power, and maintenance access so the result performs as intended.","considerations_title":"What to confirm","considerations":["Display size, pixel pitch, and viewing distance","Brightness for indoor or outdoor conditions","Content source, power routes, and control system","Mounting structure and maintenance access"],"process_eyebrow":"Workflow","process_title":"From requirements to a ready-to-use display.","process":["Surveying the site and audience needs","Selecting display specifications and configuration","Preparing structure, power, and control systems","Installation, visual testing, and handover"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Build your digital media solution.","cta_description":"Share the location, display area, viewing distance, and content needs so the LED configuration can be designed around your project.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
    when 'led-indoor' then $$ {"eyebrow":"Conventional media","title":"Conventional Media","description":"Billboards, lightboxes, and signage that communicate your brand clearly in the right location and format.","intro_eyebrow":"Planning basis","intro_title":"Physical media shaped by location and visibility.","intro":"Conventional media should account for location, traffic direction, display size, artwork, structure, lighting, and maintenance so the message stays visible and durable.","considerations_title":"What to confirm","considerations":["Location, viewing direction, and audience profile","Display size and artwork ratio","Structure, materials, and weather exposure","Lighting, power, and maintenance access"],"process_eyebrow":"Workflow","process_title":"From format selection to a finished display.","process":["Analyzing the site and visibility opportunity","Selecting the format, size, and materials","Preparing artwork, structure, and lighting","Production, installation, and final inspection"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Plan your conventional media.","cta_description":"Share the location, display area, and communication objective so the right billboard, lightbox, or signage format can be planned.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
    when 'rental-led' then $$ {"eyebrow":"Architectural & media construction","title":"Architectural & Media Construction","description":"Civil, interior, steel, facade, ballroom, and media structure solutions that integrate safely with commercial spaces and advertising media.","intro_eyebrow":"Planning basis","intro_title":"Media construction integrated with architecture.","intro":"Architectural and media construction brings together room function, structure, loading, materials, installation routes, safety, and finishing so media elements are installed cleanly and safely.","considerations_title":"What to confirm","considerations":["Building condition, dimensions, and load requirements","Facade, interior, steel, or ballroom materials","Power, cable routes, access, and site safety","Finishing, maintenance, and media integration"],"process_eyebrow":"Workflow","process_title":"From structure planning to final finishing.","process":["Reviewing drawings, site conditions, and functions","Developing structural and material details","Executing construction, installation, and site coordination","Inspecting load, finishing, and handover"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Build your architectural media solution.","cta_description":"Share the drawings, site conditions, dimensions, and media requirements so the construction solution can be reviewed with our technical team.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
    when 'media-konvensional' then $$ {"eyebrow":"Media placement & creative content","title":"Media Placement & Creative Content","description":"OOH and DOOH placement strategy combined with creative concepts, content production, and campaign rollout to reach the right audience.","intro_eyebrow":"Planning basis","intro_title":"Where media strategy meets creative thinking.","intro":"Media placement and creative content should begin with the campaign objective, audience, location, duration, media format, message, and production needs so brand communication stays relevant.","considerations_title":"What to confirm","considerations":["Campaign objective and audience profile","OOH, DOOH, location, and flighting duration","Creative concept, format, and production needs","Rollout schedule, approval, and measurement"],"process_eyebrow":"Workflow","process_title":"From strategy to a live campaign.","process":["Understanding objectives, audience, and opportunities","Building the placement strategy and creative concept","Producing and adapting content assets","Launching the rollout and reviewing results"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Connect placement with stronger content.","cta_description":"Share your campaign objective, audience, locations, and key message so media strategy and creative content can be planned as one process.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
    when 'digital-signage' then $$ {"eyebrow":"Audio visual","title":"Audio Visual","description":"Integrated audio visual systems for meeting rooms, presentation spaces, venues, and events with clear signal flow and simple operation.","intro_eyebrow":"Planning basis","intro_title":"Visual and audio systems working as one.","intro":"Audio visual planning should account for room function, users, acoustics, displays, audio, control systems, signal flow, connectivity, and daily operation.","considerations_title":"What to confirm","considerations":["Room size, user count, and acoustics","Displays, audio, microphones, and control systems","Signal flow, connectivity, and device compatibility","Ease of use, training, and maintenance"],"process_eyebrow":"Workflow","process_title":"Building a system that is easy to operate.","process":["Understanding room functions and user flow","Selecting devices, signal flow, and control systems","Installing, configuring, and integrating the system","Testing, training, and system handover"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Connect your space with better AV.","cta_description":"Share the room type, user count, existing equipment, and meeting or event needs so the audio visual system can be integrated properly.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
    when 'event-production' then $$ {"eyebrow":"Event production","title":"Event Production","description":"Visual and technical production support for events, stages, conferences, and live experiences from setup through show day.","intro_eyebrow":"Planning basis","intro_title":"Production that follows the rhythm of the event.","intro":"Event production brings together stage, screen, visual, signal, power, setup schedules, rehearsals, rundowns, and technical operation so the event runs smoothly.","considerations_title":"What to confirm","considerations":["Conference format, stage, and audience needs","Screens, visual content, signal, audio, and lighting","Setup, rehearsal, loading, and safety schedules","Team roles and technical operation support"],"process_eyebrow":"Workflow","process_title":"From rundown to show day.","process":["Reviewing the rundown, venue, and technical needs","Building the stage, screen, signal, and production plan","Setting up equipment, routing signals, and rehearsing","Operating the live event and completing breakdown"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Prepare your event with a coordinated team.","cta_description":"Share the rundown, venue, schedule, and visual requirements so production support can be planned safely and measurably.","cta_button_text":"Contact Visitiga","back_text":"All services"} $$::jsonb
  end,
  seo_title_id = case slug
    when 'videotron-outdoor' then 'Digital Media Solution | Visitiga'
    when 'led-indoor' then 'Conventional Media | Visitiga'
    when 'rental-led' then 'Architectural & Media Construction | Visitiga'
    when 'media-konvensional' then 'Media Placement & Creative Content | Visitiga'
    when 'digital-signage' then 'Audio Visual | Visitiga'
    when 'event-production' then 'Event Production | Visitiga'
  end,
  seo_description_id = case slug
    when 'videotron-outdoor' then 'Solusi layar LED indoor dan outdoor dengan perencanaan pixel pitch, brightness, jarak pandang, struktur, dan sistem kontrol.'
    when 'led-indoor' then 'Billboard, lightbox, dan signage yang dirancang berdasarkan lokasi, ukuran bidang, material, struktur, dan pencahayaan.'
    when 'rental-led' then 'Solusi konstruksi sipil, interior, baja, facade, ballroom, dan media structure yang aman serta terintegrasi.'
    when 'media-konvensional' then 'Strategi OOH dan DOOH yang dipadukan dengan creative concept, produksi konten, dan campaign rollout.'
    when 'digital-signage' then 'Sistem audio visual terintegrasi untuk meeting room, ruang presentasi, venue, dan event.'
    when 'event-production' then 'Dukungan produksi visual dan teknis untuk event, stage, conference, dan live experience.'
  end,
  seo_title_en = case slug
    when 'videotron-outdoor' then 'Digital Media Solution | Visitiga'
    when 'led-indoor' then 'Conventional Media | Visitiga'
    when 'rental-led' then 'Architectural & Media Construction | Visitiga'
    when 'media-konvensional' then 'Media Placement & Creative Content | Visitiga'
    when 'digital-signage' then 'Audio Visual | Visitiga'
    when 'event-production' then 'Event Production | Visitiga'
  end,
  seo_description_en = case slug
    when 'videotron-outdoor' then 'Indoor and outdoor LED display solutions planned around pixel pitch, brightness, viewing distance, structure, and control systems.'
    when 'led-indoor' then 'Billboards, lightboxes, and signage planned around location, display size, materials, structure, and lighting.'
    when 'rental-led' then 'Civil, interior, steel, facade, ballroom, and media structure solutions integrated safely with commercial spaces.'
    when 'media-konvensional' then 'OOH and DOOH placement strategy combined with creative concepts, content production, and campaign rollout.'
    when 'digital-signage' then 'Integrated audio visual systems for meeting rooms, presentation spaces, venues, and events.'
    when 'event-production' then 'Visual and technical production support for events, stages, conferences, and live experiences.'
  end
where slug in ('videotron-outdoor', 'led-indoor', 'rental-led', 'media-konvensional', 'digital-signage', 'event-production');

-- Replace only the original six-card fallback payload; do not overwrite customized card copy.
update public.service_content
set cards = case
  when cards->0->>'title' in ('LED Display', 'Digital Media Solution') then jsonb_build_array(
    jsonb_build_object('title','Digital Media Solution','description','Solusi layar LED indoor dan outdoor dengan visual tajam untuk berbagai kebutuhan ruang dan lokasi.','tags',jsonb_build_array('Indoor','Outdoor','Videotron'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Conventional Media','description','Billboard, lightbox, dan signage untuk menyampaikan pesan brand di lokasi yang tepat.','tags',jsonb_build_array('Billboard','Lightbox','Signage'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Architectural & Media Construction','description','Solusi struktur sipil, interior, baja, facade, ballroom, dan media structure yang terintegrasi.','tags',jsonb_build_array('Construction','Ballroom','Media Structure'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Media Placement & Creative Content','description','Strategi OOH dan DOOH yang dipadukan dengan konsep kreatif dan produksi konten.','tags',jsonb_build_array('OOH','DOOH','Campaign'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Audio Visual','description','Sistem audio visual terintegrasi untuk meeting room, presentasi, venue, dan event.','tags',jsonb_build_array('Audio','Visual','Integration'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Event Production','description','Dukungan produksi visual dan teknis untuk event, stage, conference, dan live experience.','tags',jsonb_build_array('Events','Staging','Technical Support'),'action','Konsultasi sekarang')
  ) else cards end,
  content_id = case when content_id->'cards'->0->>'title' in ('LED Display', 'Digital Media Solution') then jsonb_set(content_id, '{cards}', jsonb_build_array(
    jsonb_build_object('title','Digital Media Solution','description','Solusi layar LED indoor dan outdoor dengan visual tajam untuk berbagai kebutuhan ruang dan lokasi.','tags',jsonb_build_array('Indoor','Outdoor','Videotron'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Conventional Media','description','Billboard, lightbox, dan signage untuk menyampaikan pesan brand di lokasi yang tepat.','tags',jsonb_build_array('Billboard','Lightbox','Signage'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Architectural & Media Construction','description','Solusi struktur sipil, interior, baja, facade, ballroom, dan media structure yang terintegrasi.','tags',jsonb_build_array('Construction','Ballroom','Media Structure'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Media Placement & Creative Content','description','Strategi OOH dan DOOH yang dipadukan dengan konsep kreatif dan produksi konten.','tags',jsonb_build_array('OOH','DOOH','Campaign'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Audio Visual','description','Sistem audio visual terintegrasi untuk meeting room, presentasi, venue, dan event.','tags',jsonb_build_array('Audio','Visual','Integration'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Event Production','description','Dukungan produksi visual dan teknis untuk event, stage, conference, dan live experience.','tags',jsonb_build_array('Events','Staging','Technical Support'),'action','Konsultasi sekarang')
  ), true) else content_id end,
  content_en = case when content_en->'cards'->0->>'title' in ('LED Display', 'Digital Media Solution') then jsonb_set(content_en, '{cards}', jsonb_build_array(
    jsonb_build_object('title','Digital Media Solution','description','Indoor and outdoor LED display solutions with sharp visuals for different spaces and locations.','tags',jsonb_build_array('Indoor','Outdoor','Videotron'),'action','Consult now'),
    jsonb_build_object('title','Conventional Media','description','Billboards, lightboxes, and signage that communicate your brand in the right location.','tags',jsonb_build_array('Billboard','Lightbox','Signage'),'action','Consult now'),
    jsonb_build_object('title','Architectural & Media Construction','description','Civil, interior, steel, facade, ballroom, and media structure solutions designed to work together.','tags',jsonb_build_array('Construction','Ballroom','Media Structure'),'action','Consult now'),
    jsonb_build_object('title','Media Placement & Creative Content','description','OOH and DOOH placement strategy combined with creative concepts and content production.','tags',jsonb_build_array('OOH','DOOH','Campaign'),'action','Consult now'),
    jsonb_build_object('title','Audio Visual','description','Integrated audio visual systems for meeting rooms, presentations, venues, and events.','tags',jsonb_build_array('Audio','Visual','Integration'),'action','Consult now'),
    jsonb_build_object('title','Event Production','description','Visual and technical production support for events, stages, conferences, and live experiences.','tags',jsonb_build_array('Events','Staging','Technical Support'),'action','Consult now')
  ), true) else content_en end
where id = 1;
